<header class="admin-page-head"><div><span class="eyebrow">Commerce</span><h1>سفارش‌ها و پرداخت‌ها</h1><p>پیگیری کامل سفارش، پرداخت، وضعیت ثبت‌نام و خطاهای درگاه.</p></div><span class="admin-count"><?= number_format($pagination['total']) ?> سفارش</span></header>
<div class="admin-status-strip"><a class="<?= $filters['status']==='all'?'is-active':'' ?>" href="/admin/orders">همه <b><?= number_format(array_sum($statusCounts)) ?></b></a><?php foreach($statusCounts as $status=>$count):?><a class="<?= $filters['status']===$status?'is-active':'' ?>" href="/admin/orders?status=<?=e($status)?>"><?=e($status)?> <b><?=number_format($count)?></b></a><?php endforeach;?></div>
